package org.apache.commons.math.optimization;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.ConvergenceException;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.apache.commons.math.exception.ConvergenceException;
import org.apache.commons.math.exception.FunctionEvaluationException;
import org.apache.commons.math.optimization.univariate.GoalType;
import org.apache.commons.math.optimization.univariate.UnivariateRealFunction;
import org.apache.commons.math.random.RandomGenerator;
import org.apache.commons.math.util.LocalizedFormats;
import org.apache.commons.math3.random.JDKRandomGenerator;
import org.apache.commons.math3.random.RandomGenerator;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyDouble;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class MultiStartUnivariateRealOptimizer_optimize_TriageGen2Test {

    private UnivariateRealOptimizer mockOptimizer;
    private RandomGenerator mockGenerator;
    private UnivariateRealFunction function;

    @Before
    public void setUp() {
        mockOptimizer = mock(UnivariateRealOptimizer.class);
        mockGenerator = mock(RandomGenerator.class);
        function = f -> f.value(0); // Dummy implementation
    }

    @Test
    public void testOptimize_SuccessMaximize() throws ConvergenceException, FunctionEvaluationException {
        // Setup: 2 starts. First start succeeds, second start succeeds.
        // We want to test the sorting logic for MAXIMIZE.
        MultiStartUnivariateRealOptimizer multiStartOptimizer = new MultiStartUnivariateRealOptimizer(mockOptimizer, 2, mockGenerator);

        when(mockOptimizer.optimize(any(), eq(GoalType.MAXIMIZE), anyDouble(), anyDouble()))
                .thenReturn(1.0) // Start 1
                .thenReturn(2.0); // Start 2

        when(mockOptimizer.getFunctionValue())
                .thenReturn(10.0) // Value for x=1.0
                .thenReturn(20.0); // Value for x=2.0

        double result = multiStartOptimizer.optimize(function, GoalType.MAXIMIZE, 0.0, 5.0);

        assertEquals(2.0, result, 1e-10);
        assertEquals(20.0, multiStartOptimizer.getOptimaValues()[0], 1e-10);
    }

    @Test
    public void testOptimize_SuccessMinimize() throws ConvergenceException, FunctionEvaluationException {
        // Setup: 2 starts.
        MultiStartUnivariateRealOptimizer multiStartOptimizer = new MultiStartUnivariateRealOptimizer(mockOptimizer, 2, mockGenerator);

        when(mockOptimizer.optimize(any(), eq(GoalType.MINIMIZE), anyDouble(), anyDouble()))
                .thenReturn(1.0)
                .thenReturn(2.0);

        when(mockOptimizer.getFunctionValue())
                .thenReturn(20.0) // x=1.0, y=20
                .thenReturn(10.0); // x=2.0, y=10

        double result = multiStartOptimizer.optimize(function, GoalType.MINIMIZE, 0.0, 5.0);

        assertEquals(2.0, result, 1e-10);
        assertEquals(10.0, multiStartOptimizer.getOptimaValues()[0], 1e-10);
    }

    @Test
    public void testOptimize_AllFail_ThrowsOptimizationException() throws ConvergenceException, FunctionEvaluationException {
        MultiStartUnivariateRealOptimizer multiStartOptimizer = new MultiStartUnivariateRealOptimizer(mockOptimizer, 1, mockGenerator);

        when(mockOptimizer.optimize(any(), any(), anyDouble(), anyDouble()))
                .thenThrow(new ConvergenceException(new RuntimeException()));

        assertThrows(OptimizationException.class, () -> {
            multiStartOptimizer.optimize(function, GoalType.MAXIMIZE, 0.0, 5.0);
        });
    }

    @Test
    public void testOptimize_PartialFailures_SortingWithNaN() throws ConvergenceException, FunctionEvaluationException {
        // Setup: 3 starts. 1 fails (NaN), 2 succeed.
        MultiStartUnivariateRealOptimizer multiStartOptimizer = new MultiStartUnivariateRealOptimizer(mockOptimizer, 3, mockGenerator);

        // Mocking behavior for 3 starts
        when(mockOptimizer.optimize(any(), any(), anyDouble(), anyDouble()))
                .thenReturn(1.0) // Start 0: Success
                .thenThrow(new FunctionEvaluationException(new RuntimeException())) // Start 1: Fail
                .thenReturn(2.0); // Start 2: Success

        when(mockOptimizer.getFunctionValue())
                .thenReturn(50.0)
                .thenReturn(100.0);

        // To ensure random bounds are generated for starts > 0
        when(mockGenerator.nextDouble()).thenReturn(0.5);

        double result = multiStartOptimizer.optimize(function, GoalType.MAXIMIZE, 0.0, 10.0);

        // Best should be x=2.0 (y=100)
        assertEquals(2.0, result, 1e-10);

        double[] optima = multiStartOptimizer.getOptima();
        double[] values = multiStartOptimizer.getOptimaValues();

        // Check that NaN is moved to the end
        assertEquals(100.0, values[0], 1e-10);
        assertEquals(50.0, values[1], 1e-10);
        assertEquals(Double.NaN, values[2]);
    }

    @Test
    public void testOptimize_ComplexSortingLogic() throws ConvergenceException, FunctionEvaluationException {
        // testing the insertion sort logic with multiple elements
        MultiStartUnivariateRealOptimizer multiStartOptimizer = new MultiStartUnivariateRealOptimizer(mockOptimizer, 4, mockGenerator);

        // Returns x values in order 1, 2, 3, 4
        when(mockOptimizer.optimize(any(), eq(GoalType.MAXIMIZE), anyDouble(), anyDouble()))
                .thenReturn(1.0, 2.0, 3.0, 4.0);

        // Function values: 10, 40, 20, 30 (unsorted)
        when(mockOptimizer.getFunctionValue())
                .thenReturn(10.0, 40.0, 20.0, 30.0);

        double result = multiStartOptimizer.optimize(function, GoalType.MAXIMIZE, 0.0, 10.0);

        // Highest is 40.0 at x=2.0
        assertEquals(2.0, result, 1e-10);
        assertEquals(40.0, multiStartOptimizer.getOptimaValues()[0], 1e-10);

        // Sorted values should be 40, 30, 20, 10
        assertEquals(40.0, multiStartOptimizer.getOptimaValues()[0], 1e-10);
        assertEquals(30.0, multiStartOptimizer.getOptimaValues()[1], 1e-10);
        assertEquals(20.0, multiStartOptimizer.getOptimaValues()[2], 1e-10);
        assertEquals(10.0, multiStartOptimizer.getOptimaValues()[3], 1e-10);
    }

    @Test
    public void testOptimize_ConvergenceExceptionInLoop() throws ConvergenceException, FunctionEvaluationException {
        MultiStartUnivariateRealOptimizer multiStartOptimizer = new MultiStartUnivariateRealOptimizer(mockOptimizer, 2, mockGenerator);

        // First start throws ConvergenceException, second succeeds
        when(mockOptimizer.optimize(any(), any(), anyDouble(), anyDouble()))
                .thenThrow(new ConvergenceException(new RuntimeException()))
                .thenReturn(5.0);

        when(mockOptimizer.getFunctionValue()).thenReturn(100.0);

        double result = multiStartOptimizer.optimize(function, GoalType.MAXIMIZE, 0.0, 10.0);
        assertEquals(5.0, result, 1e-10);
    }
}
